package android.content;import java.io.*;import java.util.*;import android.content.pm.ApplicationInfo;public class Context {final File root;final Map<String,SharedPreferences> preferences=new HashMap<>();public Context(File f){root=f;root.mkdirs();}public Context getApplicationContext(){return this;}public synchronized SharedPreferences getSharedPreferences(String name,int mode){return preferences.computeIfAbsent(name,n->new SharedPreferences());}public File getNoBackupFilesDir(){return root;}public ApplicationInfo getApplicationInfo(){return new ApplicationInfo();}}
